"""Mathematics lessons 6 and 7: ratio and average. All worked numbers are original."""
from fractions import Fraction as F
from math import gcd, isqrt
from math_kit import B, explore, fr, match, mcq, num, order, part, solve, story, stepwise, tf, unit
from math_labs import task


def lab(sid, title, text, widget, tasks):
    return {**story(sid, title, [text], widget=widget), "tasks": tasks}


def diagram(sid, title, text, layout, items):
    return story(sid, title, text, diagram={"layout": layout, "items": items})


def lcm(a, b):
    return a * b // gcd(a, b)


